#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "Record data in a hint — additionalProperties: false catches `actionId`. An event says which topic to re-read, never what changed; the record comes from the signed read, where authorization is decided.",
            "{\n  \"actionId\": \"act_7Hq2mZp9Lx4vRk8T\",\n  \"at\": \"2026-10-03T09:15:00Z\",\n  \"count\": 2,\n  \"resumeToken\": \"evt.000142\",\n  \"topic\": \"actions\"\n}",
        ),
        (
            "Personal data in a hint — additionalProperties: false catches `applicant`. A join-request hint carries a count, never who applied.",
            "{\n  \"applicant\": \"did:web:dave.example\",\n  \"at\": \"2026-10-03T09:15:00Z\",\n  \"count\": 1,\n  \"resumeToken\": \"evt.000143\",\n  \"topic\": \"joinRequests\"\n}",
        ),
        (
            "`topic` outside the closed enum — each topic is bound to the read that authorizes it, so an unknown topic has no read to check entitlement against.",
            "{\n  \"at\": \"2026-10-03T09:15:00Z\",\n  \"resumeToken\": \"evt.000144\",\n  \"topic\": \"auditLog\"\n}",
        ),
        (
            "`resumeToken` is required — without it a console that reconnects cannot resume, and must re-read everything.",
            "{\n  \"at\": \"2026-10-03T09:15:00Z\",\n  \"topic\": \"members\"\n}",
        ),
        (
            "Negative `count` — a badge count cannot be below zero.",
            "{\n  \"at\": \"2026-10-03T09:15:00Z\",\n  \"count\": -1,\n  \"resumeToken\": \"evt.000145\",\n  \"topic\": \"acknowledgements\"\n}",
        ),
        (
            "`at` must be an RFC 3339 date-time.",
            "{\n  \"at\": \"just now\",\n  \"resumeToken\": \"evt.000146\",\n  \"topic\": \"config\"\n}",
        ),
        (
            "`resumeToken` with a newline — it is carried as the SSE `id` field over HTTPS, where a line break would end the field and corrupt the stream.",
            "{\n  \"at\": \"2026-10-03T09:15:00Z\",\n  \"resumeToken\": \"evt.000147\\ndata: {}\",\n  \"topic\": \"singleAdminMode\"\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
